// STUB — Phase 8 Skeleton
// PURPOSE: Validate creative brief against creative-brief.schema.json required fields
// SCHEMA REF: schemas/creative-brief.schema.json
// REQUIRED FIELDS: brief_id, brand_id, brand_name, asset_type, platform, format,
//   objective, concept, visual_direction, approval_status, created_by_agent, created_at

const inputData = $input.first().json;
const brief = inputData.creativeBrief || {};

const requiredFields = [
  'brief_id', 'brand_id', 'brand_name', 'asset_type',
  'platform', 'format', 'objective', 'concept',
  'visual_direction', 'approval_status', 'created_by_agent', 'created_at'
];

const missingFields = requiredFields.filter(f => !brief[f] || brief[f] === '');
const validationPass = missingFields.length === 0;
const validationErrors = missingFields.map(f => `SCHEMA_VALIDATION_FAIL: Missing required field: ${f}`);

return [{ json: { ...inputData, validation_pass: validationPass, validation_errors: validationErrors } }];

// STUB — Phase 8 Skeleton
// PURPOSE: Write structured log entry per schemas/log-entry.schema.json
// PRODUCTION: Append row to Google Sheets log tab or Supabase logs table
// CREDENTIAL NEEDED: REPLACE_WITH_GOOGLE_SHEETS_CREDENTIAL or REPLACE_WITH_SUPABASE_CREDENTIAL
// CONSTRAINT: No real write in skeleton.

const inputData = $input.first().json;
const brief = inputData.creativeBrief || {};

const logEntry = {
  log_id: 'LOG-' + new Date().toISOString().slice(0, 10).replace(/-/g, '') + '-STUB-001',
  timestamp: new Date().toISOString(),
  phase: '8',
  agent_name: 'n8n-creative-asset-auto (STUB)',
  action_type: 'Creative Brief Draft',
  input_ref: inputData.brief_request || 'STUB_INPUT',
  output_ref: brief.brief_id || 'STUB_OUTPUT',
  status: 'Success',
  summary: 'Creative Asset Auto skeleton executed. Brief created with approval_status=Draft. No real AI call.',
  errors: (inputData.validation_errors && inputData.validation_errors.length) ? inputData.validation_errors : null,
  next_action: 'Send brief to approval queue. Owner to review and set approval_status=Approved before asset production.',
  owner_action_required: false
};

return [{ json: { ...inputData, logEntry, logWritten: true } }];
